changeSet.sql:
create or alter procedure dbo.ReadFeatureFlagForCompany
	@companyId int,
	@slug varchar(100)
as
begin 
	select	coalesce(c.[Value], f.DefaultValue) as [Value]
	from	FeatureFlag f
			left join CompanyFeatureFlag c on c.FeatureFlagId = f.Id and c.CompanyID = @companyId
	where	f.Slug = @slug;
end
